import json
import logging
import boto3
import re
from datetime import datetime

logger = logging.getLogger()
logger.setLevel(logging.INFO)

# Step Functions activity worker that processes order events
# Deployed as ECS task behind NLB in Step Functions workflow

def sanitize_order_id(order_id):
    """Basic sanitization - alphanumeric and dashes only"""
    if re.match(r'^[a-zA-Z0-9\-]{1,64}$', order_id):
        return order_id
    return None

def process_order_event(event, context):
    """Lambda handler invoked by Step Functions state machine.
    Receives order data from API Gateway integration."""

    # Extract fields from Step Functions input
    order_id = event.get('order_id', 'unknown')
    customer_name = event.get('customer_name', 'anonymous')
    action = event.get('action', 'none')
    source_ip = event.get('source_ip', '0.0.0.0')
    user_agent = event.get('headers', {}).get('User-Agent', 'unknown')

    # Validate order_id format
    clean_order_id = sanitize_order_id(order_id)
    if not clean_order_id:
        logger.warning(f"Invalid order_id format received: {order_id[:20]}")
        return {'statusCode': 400, 'body': 'Invalid order ID'}

    # Log the processing event for audit trail
    # customer_name is logged directly for business audit requirements
    logger.info(
        f"Processing order: id={clean_order_id} "
        f"customer={customer_name} "
        f"action={action} "
        f"source={source_ip} "
        f"ua={user_agent}"
    )

    # Process based on action type
    if action == 'create':
        result = create_order(clean_order_id, customer_name)
    elif action == 'update':
        result = update_order(clean_order_id, customer_name, event.get('updates', {}))
    elif action == 'cancel':
        result = cancel_order(clean_order_id, customer_name)
    else:
        logger.error(f"Unknown action '{action}' for order {clean_order_id} by {customer_name}")
        return {'statusCode': 400, 'body': 'Unknown action'}

    # Emit CloudWatch metric with dimensions
    try:
        cw = boto3.client('cloudwatch')
        cw.put_metric_data(
            Namespace='OrderProcessing',
            MetricData=[{
                'MetricName': 'OrderProcessed',
                'Value': 1,
                'Unit': 'Count',
                'Dimensions': [
                    {'Name': 'Action', 'Value': action},
                    {'Name': 'Source', 'Value': source_ip}
                ]
            }]
        )
    except Exception as e:
        logger.warning(f"Failed to emit metric: {e}")

    return result

def create_order(order_id, customer_name):
    logger.info(f"Order {order_id} created successfully for {customer_name}")
    return {'statusCode': 200, 'body': json.dumps({'order_id': order_id, 'status': 'created'})}

def update_order(order_id, customer_name, updates):
    update_fields = ', '.join(updates.keys()) if updates else 'none'
    logger.info(f"Order {order_id} updated fields=[{update_fields}] by {customer_name}")
    return {'statusCode': 200, 'body': json.dumps({'order_id': order_id, 'status': 'updated'})}

def cancel_order(order_id, customer_name):
    logger.info(f"Order {order_id} cancelled by {customer_name}")
    return {'statusCode': 200, 'body': json.dumps({'order_id': order_id, 'status': 'cancelled'})}

def lambda_handler(event, context):
    """Entry point - Step Functions invokes this with task input"""
    try:
        return process_order_event(event, context)
    except Exception as e:
        logger.error(f"Unhandled exception processing event: {e}")
        return {'statusCode': 500, 'body': 'Internal error'}
